#!/usr/bin/env python3
"""Drain explicitly admitted Income research only; existing hourly caller owns cadence."""
import datetime as dt
import fcntl
import hashlib
import importlib.util
import json
import os
from pathlib import Path
import sys
import time
import stat
import urllib.request

ROOT = Path("/var/lib/ziji-fabric/dispatch/continuation")
QUEUE = Path("/etc/ziji-fabric/dispatch/income-queue.json")
RUNTIME = Path("/opt/ziji-fabric/income/career_unit.py")

def read(path, max_bytes=1048576, expected_sha256=None):
    if path.is_symlink() or not stat.S_ISREG(path.stat().st_mode) or path.stat().st_mode & 0o077 or path.stat().st_size > max_bytes:
        raise ValueError("private_regular_file_required")
    raw = path.read_bytes()
    if len(raw) > max_bytes: raise ValueError("private_file_too_large")
    if expected_sha256 is not None and hashlib.sha256(raw).hexdigest() != expected_sha256:
        raise ValueError("snapshot_digest_mismatch")
    return json.loads(raw)

def save(path, value):
    temp = path.with_name(path.name + "." + os.urandom(8).hex())
    fd = os.open(temp, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
    try:
        with os.fdopen(fd, "w") as out:
            json.dump(value, out, sort_keys=True); out.flush(); os.fsync(out.fileno())
        os.replace(temp, path)
    finally:
        if temp.exists(): temp.unlink()

def timeof(value):
    import re
    # Older native Python requires a colon in Jira's numeric UTC offset.
    # Normalize only the parser input; exact source strings remain CAS evidence.
    parsed_value = re.sub(r"([+-][0-9]{2})([0-9]{2})$", r"\1:\2", value.replace("Z", "+00:00"))
    stamp = dt.datetime.fromisoformat(parsed_value)
    if stamp.tzinfo is None: raise ValueError("aware_time_required")
    return stamp

def identity(intake):
    # Canonical refresh may not turn a completed packet into another job.
    return hashlib.sha256(json.dumps(
        [intake[k] for k in ("tracker_url", "packet_id", "job_id")],
        separators=(",", ":")).encode()).hexdigest()

def admitted(entry, now):
    intake = entry["intake"]
    canonical = entry["canonical"]
    if not entry.get("authority_ref") or canonical.get("do_not_submit") is not True:
        return False
    if any(canonical.get(k) != intake.get(k) for k in
           ("tracker_url", "packet_id", "job_id", "tracker_version")):
        return False
    age = (now - timeof(intake["observed_at"])).total_seconds()
    return 0 <= age <= 36 * 3600 and now < timeof(entry["expires_at"])


ADMISSION_POLICY = Path("/etc/ziji-fabric/dispatch/income-admission.json")
SOURCES = Path("/var/lib/ziji-fabric/native-sources")
MARKER = "FABRIC_INCOME_ADMISSION"

def validate_policy(policy):
    """Reusable installer validation; values stay in root-private configuration."""
    import re
    if (not isinstance(policy, dict) or type(policy.get("enabled")) is not bool or
        policy.get("authority_ref") != "RBO-97:12086" or
        not re.fullmatch(r"[A-Za-z0-9:_-]{1,128}", str(policy.get("issuer_account_id", ""))) or
        not re.fullmatch(r"[A-Za-z0-9_-]{1,128}", str(policy.get("drive_folder", "")))):
        raise ValueError("admission_policy_invalid")
    timeof(policy["authority_comment_updated"])
    return policy

def highlevel_reference(value):
    """Typed native reference, supplied outside the hashed source payload."""
    import re
    required = {"source_id","location_id","contact_id","current_source_sha256"}
    if not isinstance(value,dict) or not required <= set(value) or set(value)-required-{"opportunity_id"}:
        raise ValueError("highlevel_reference_invalid")
    if not isinstance(value["source_id"],str) or not 1 <= len(value["source_id"]) <= 200:
        raise ValueError("highlevel_reference_invalid")
    for key in ("location_id","contact_id","opportunity_id"):
        if key in value and not re.fullmatch(r"[A-Za-z0-9_-]{1,128}",str(value[key])):
            raise ValueError("highlevel_reference_invalid")
    if not re.fullmatch(r"[a-f0-9]{64}",str(value["current_source_sha256"])):
        raise ValueError("highlevel_reference_invalid")
    return dict(value)

def highlevel_identity(ref):
    value = "highlevel://location/"+ref["location_id"]+"/contact/"+ref["contact_id"]
    if ref.get("opportunity_id"): value += "/opportunity/"+ref["opportunity_id"]
    return value

def verify_highlevel_values(entry, value):
    import re
    ref = highlevel_reference(entry["canonical"]["highlevel"])
    if (value.get("native_readback") is not True or value.get("domain") != "income"
            or value.get("operational_system") != "highlevel"
            or any(value.get(k) != ref.get(k) for k in ("source_id","location_id","contact_id","opportunity_id"))
            or value.get("source_sha256") != ref["current_source_sha256"]):
        raise ValueError("highlevel_source_changed")
    intake = entry["intake"]
    expected = {k:intake[k] for k in ("provider","board","job_id","title","packet_id")}
    expected.update(do_not_submit=True,duplicate_clear=True,artifact_absent=True)
    # The source records facts; only the outer Jira approval authorizes execution.
    # No source digest/self-reference belongs inside this source-hashed projection.
    if value.get("admission_projection") != expected:
        raise ValueError("highlevel_admission_facts_changed")
    aliases = value.get("legacy_provenance_urls",[])
    if not isinstance(aliases,list):raise ValueError("highlevel_source_alias_invalid")
    legacy = {url for url in aliases if isinstance(url,str) and re.fullmatch(r"https://app.notion.com/p/[a-f0-9]{32}",url)}
    if len(legacy)>1:raise ValueError("highlevel_source_alias_ambiguous")
    expected_identity = next(iter(legacy)) if legacy else highlevel_identity(ref)
    if intake["tracker_url"] != expected_identity or intake["tracker_version"] != ref["current_source_sha256"]:
        raise ValueError("highlevel_identity_alias_changed")

def verify_highlevel(entry):
    """Read through the existing sole bridge, reusing its server-private caller key."""
    import shlex
    env = Path("/etc/bridgeghl/bridgeghl.env")
    if (env.is_symlink() or not stat.S_ISREG(env.stat().st_mode) or env.stat().st_uid != 0
            or env.stat().st_mode & 0o077 or env.stat().st_size > 1048576):
        raise ValueError("bridge_binding_private_file_required")
    keys = []
    for line in env.read_text().splitlines():
        name,sep,value = line.partition("=")
        if sep and name.strip() == "BRIDGE_API_KEY":
            parsed=shlex.split(value,comments=True)
            if len(parsed)==1: keys.append(parsed[0])
    if len(keys)!=1 or not keys[0]:raise ValueError("bridge_caller_binding_missing")
    ref = entry["canonical"]["highlevel"]
    payload = {k:v for k,v in ref.items() if k!="location_id"}
    class NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self,*args,**kwargs):return None
    request = urllib.request.Request("http://127.0.0.1:8000/read/ingest/income-source",
        data=json.dumps(payload).encode(),headers={"x-api-key":keys[0],"Content-Type":"application/json"})
    opener=urllib.request.build_opener(urllib.request.ProxyHandler({}),NoRedirect)
    with opener.open(request,timeout=90) as response:
        raw=response.read(1048577)
        if len(raw)>1048576:raise ValueError("highlevel_readback_too_large")
        value=json.loads(raw)
    verify_highlevel_values(entry,value)

def projection(row, policy, now):
    """Strict typed factual projection from the explicitly registered canonical bridge."""
    import re
    if not isinstance(row, dict): raise ValueError("admission_row_invalid")
    if row.get("author_account_id") != policy["issuer_account_id"]:
        raise ValueError("admission_issuer_mismatch")
    editor = row.get("update_author_account_id")
    if editor != policy["issuer_account_id"]:
        raise ValueError("admission_editor_mismatch")
    if not re.fullmatch(r"[0-9]{1,30}", str(row.get("id", ""))):
        raise ValueError("admission_comment_identity")
    body = row["body"].strip()
    prefix, separator, raw = body.partition("\n")
    if prefix != MARKER or not separator or len(raw) > 16384:
        raise ValueError("admission_marker_invalid")
    value = json.loads(raw)
    if not isinstance(value, dict): raise ValueError("admission_object_required")
    if (value.get("schema_version") != 1 or value.get("status") != "ACTIVE" or
        value.get("action_class") != "source_bound_career_research_draft" or
        value.get("authority_ref") != policy["authority_ref"]):
        raise ValueError("admission_scope_invalid")
    intake, canonical = value["intake"], value["canonical"]
    if not isinstance(intake, dict) or not isinstance(canonical, dict): raise ValueError("admission_object_required")
    keys = ("provider", "board", "job_id", "title", "packet_id", "tracker_url",
            "tracker_version", "observed_at", "drive_folder")
    if any(not isinstance(intake.get(k), str) or not 0 < len(intake[k]) <= 500 for k in keys):
        raise ValueError("admission_fields_invalid")
    native = highlevel_reference(canonical["highlevel"]) if "highlevel" in canonical else None
    legacy_url = bool(re.fullmatch(r"https://app.notion.com/p/[a-f0-9]{32}",intake["tracker_url"]))
    valid_tracker = legacy_url or (native is not None and intake["tracker_url"] == highlevel_identity(native))
    if native is not None and intake["tracker_version"] != native["current_source_sha256"]:
        raise ValueError("highlevel_version_mismatch")
    if (intake["provider"] not in ("ashby", "lever") or
        not re.fullmatch(r"[a-z0-9-]{1,60}", intake["board"]) or
        not re.fullmatch(r"[a-f0-9-]{36}", intake["job_id"]) or
        not re.fullmatch(r"[A-Za-z0-9-]{1,100}", intake["packet_id"]) or
        not valid_tracker or
        intake["drive_folder"] != policy["drive_folder"]):
        raise ValueError("admission_target_invalid")
    if canonical.get("duplicate_clear") is not True or canonical.get("artifact_absent") is not True:
        raise ValueError("admission_duplicate_attestation_missing")
    # Only known fields cross into the actor. No supplied instructions, URLs or shell arguments.
    entry = {"intake": {k:intake[k] for k in keys},
             "canonical": {k:canonical.get(k) for k in
                ("job_id","packet_id","tracker_url","tracker_version","do_not_submit")},
             "authority_ref":policy["authority_ref"], "expires_at":value["expires_at"]}
    if native is not None:entry["canonical"]["highlevel"] = native
    if not admitted(entry, now) or timeof(entry["expires_at"]) > timeof(intake["observed_at"]) + dt.timedelta(hours=36):
        raise ValueError("admission_not_current")
    entry["_jira"] = {"id":str(row["id"]), "updated":row["updated"],
                     "payload_sha256":hashlib.sha256(raw.encode()).hexdigest()}
    return entry

def reconcile(document, policy, snapshot, collection, now):
    manual = [e for e in document["items"] if "_jira" not in e]
    if policy.get("enabled") is not True:
        return {"version":1,"items":manual}, "canonical_bridge_disabled"
    age = (now - timeof(snapshot["observed_at"])).total_seconds()
    if (snapshot.get("source_verified") is not True or
        snapshot.get("coverage") != "all_issue_comments" or not 0 <= age <= 90*60 or
        collection.get("observed_at") != snapshot["observed_at"] or
        collection.get("jira",{}).get("status") != "retrieved_and_persisted"):
        raise ValueError("canonical_snapshot_unavailable")
    rows = snapshot["income_admission_candidates"]
    if not isinstance(rows, list) or len(rows) > 128:
        raise ValueError("canonical_snapshot_invalid")
    managed, ambiguous = {}, set()
    for row in rows:
        try: entry = projection(row, policy, now)
        except (ValueError, KeyError, TypeError): continue
        key = identity(entry["intake"])
        if key in managed: ambiguous.add(key)
        managed[key] = entry
    manual_ids = {identity(e["intake"]) for e in manual}
    result = manual + [entry for key,entry in managed.items() if key not in ambiguous | manual_ids]
    if len(result) > 32: raise ValueError("queue_capacity")
    return {"version":1,"items":result}, "canonical_projection_reconciled"

def refresh_admissions(document, queue, now):
    if not ADMISSION_POLICY.exists():
        # Never execute managed work if its trust configuration vanished.
        return {"version":1,"items":[e for e in document["items"] if "_jira" not in e]}, None
    try:
        policy = validate_policy(read(ADMISSION_POLICY))
        collection = read(SOURCES/"latest.json")
        digest = collection.get("jira",{}).get("snapshot_sha256")
        if not isinstance(digest, str) or len(digest) != 64: raise ValueError("snapshot_digest_missing")
        snapshot = read(SOURCES/"jira.json", max_bytes=16*1048576, expected_sha256=digest)
        updated, status = reconcile(document, policy, snapshot, collection, now)
    except (OSError, ValueError, KeyError, TypeError):
        return {"version":1,"items":[e for e in document["items"] if "_jira" not in e]}, None
    if updated != document: save(queue, updated)
    return updated, policy

def verify_projection(entry, policy, now):
    """Exact live CAS before a managed effect; credential remains in existing binding."""
    import base64
    sys.path.insert(0, "/opt/ziji-fabric/native")
    from collect_native_sources import config, text_content, request, JIRA_ROOT
    cfg = config("jira")
    if cfg.get("base_url") != JIRA_ROOT or cfg.get("project_allowlist") != ["RBO"]:
        raise ValueError("jira_binding_scope_mismatch")
    headers = {"Authorization":"Basic "+base64.b64encode((cfg["email"]+":"+cfg["api_token"]).encode()).decode()}
    def get(comment_id):
        return request(JIRA_ROOT+"/rest/api/3/issue/RBO-97/comment/"+comment_id, headers)
    authority = get("12086")
    value = get(entry["_jira"]["id"])
    return verify_projection_values(entry, policy, now, authority, value, text_content)

def verify_projection_values(entry, policy, now, authority, value, text_content):
    if (policy.get("authority_ref") != "RBO-97:12086" or
        not policy.get("authority_comment_updated") or
        authority.get("updated") != policy["authority_comment_updated"] or
        authority.get("author",{}).get("accountId") != policy["issuer_account_id"] or
        authority.get("updateAuthor",{}).get("accountId") != policy["issuer_account_id"]):
        raise ValueError("approval_source_changed")
    row = {"id":value.get("id"),"created":value.get("created"),"updated":value.get("updated"),
           "author_account_id":value.get("author",{}).get("accountId"),
           "update_author_account_id":value.get("updateAuthor",{}).get("accountId"),
           "body":text_content(value.get("body",{}))}
    current = projection(row, policy, now)
    if current != entry: raise ValueError("canonical_projection_changed")

def healthy():
    class NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, *args, **kwargs): return None
    key = Path("/etc/ziji-fabric/local-inference/api-key")
    try:
        if key.is_symlink() or key.stat().st_mode & 0o077: return False
        req = urllib.request.Request("http://127.0.0.1:18182/health",
            headers={"Authorization": "Bearer " + key.read_text().strip()})
        opener = urllib.request.build_opener(urllib.request.ProxyHandler({}), NoRedirect)
        with opener.open(req, timeout=3) as response:
            return response.status == 200 and json.loads(response.read(4096)).get("status") == "ok"
    except Exception:
        return False

DAILY_MODEL_LIMIT = 24

def reservations(ledger,day):
    value=ledger.setdefault("model_days",{}).get(day,[])
    return [value] if isinstance(value,dict) and value else value

def reserve(ledger, statefile, now, request_id, unit):
    day = now.astimezone(dt.timezone.utc).date().isoformat()
    used=reservations(ledger,day)
    if len(used)>=DAILY_MODEL_LIMIT:raise ValueError("daily_model_budget_reserved")
    previous=unit.get("request_id")
    if previous and previous!=request_id:raise ValueError("changed_source_requires_readmission")
    ledger["model_days"][day]=used+[{"request_id":request_id,"reserved_at":now.isoformat()}]
    unit["request_id"]=request_id
    save(statefile,ledger)

def tick(root=ROOT, queue=QUEUE, now=None, health=healthy, invoke=None, native_select=None, native_verify=None, native_writeback=None):
    now = now or dt.datetime.now(dt.timezone.utc)
    statefile = root / "state.json"
    ledger = read(statefile) if statefile.exists() else {"units": {}, "model_days": {}}
    def result(status, **fields):
        receipt = {"status": status, "observed_at": now.isoformat(), "scope": "admitted_income_research_only",
                   "paid_fallback": False, "submitted": 0, "contacted": 0, **fields}
        save(root / "latest.json", receipt)
        return receipt
    if (root / "pause").exists(): return result("DEFERRED", reason="operator_paused")
    if not queue.exists(): return result("WAITING", reason="no_admitted_queue")
    document = read(queue)
    if document.get("version") != 1 or len(document.get("items", [])) > 32:
        raise ValueError("invalid_queue")
    document, policy = refresh_admissions(document, queue, now)
    if native_select is not None:
        if not health():return result("DEFERRED",reason="local_model_offline_or_paused")
        try:
            document=native_select(document,ledger,now)
            save(queue,document);save(statefile,ledger)
        except Exception:
            ledger["backlog_observation"]={"status":"DEFERRED","reason":"native_backlog_source_or_authority_unavailable","observed_at":now.isoformat()}
            save(statefile,ledger)
    selected = None
    for entry in document["items"]:
        key = identity(entry["intake"])
        unit = ledger["units"].get(key, {})
        if unit.get("status") == "VERIFIED": continue
        if unit.get("next_attempt_at") and now < timeof(unit["next_attempt_at"]): continue
        if admitted(entry, now) or ("_native" in entry and unit.get("result",{}).get("phase")=="VERIFIED"):
            selected = (entry, key, unit); break
    if selected is None: return result("WAITING", reason="no_fresh_unfinished_admission")
    entry, key, unit = selected
    day = now.astimezone(dt.timezone.utc).date().isoformat()
    if not unit.get("request_id") and len(reservations(ledger,day)) >= DAILY_MODEL_LIMIT:
        return result("DEFERRED", reason="daily_model_budget_reserved", unit=key)
    if not health(): return result("DEFERRED", reason="local_model_offline_or_paused", unit=key)
    unit["job_identity"]=":".join(entry["intake"].get(k,"ashby" if k=="provider" else "") for k in ("provider","board","job_id"))
    unit["attempts"] = unit.get("attempts", 0) + 1
    unit["next_attempt_at"] = (now + dt.timedelta(hours=6)).isoformat()
    unit["status"] = "IN_PROGRESS"
    ledger["units"][key] = unit
    save(statefile, ledger)  # Crash preserves backoff before provider access.
    def budget(request_id):
        reserve(ledger, statefile, now, request_id, unit)
    try:
        if "_native" in entry:
            if native_verify is None:raise ValueError("native_backlog_verifier_unavailable")
            # A completed runtime only needs idempotent canonical writeback recovery.
            if unit.get("result",{}).get("phase") != "VERIFIED":native_verify(entry)
        if "_jira" in entry: verify_projection(entry, policy, now)
        if "highlevel" in entry["canonical"] and "_native" not in entry:verify_highlevel(entry)
        output = dict(unit["result"]) if "_native" in entry and unit.get("result",{}).get("phase")=="VERIFIED" else invoke(entry["intake"], budget)
        if "_native" in entry and output.get("phase")=="VERIFIED":
            unit["result"]={k:output[k] for k in ("phase","drive_url","artifact_sha256","receipt") if k in output}
            save(statefile,ledger)
            if native_writeback is None:raise ValueError("native_writeback_unavailable")
            output["canonical_writeback"]=native_writeback(entry,output)
        verified = output.get("phase") == "VERIFIED" and output.get("receipt", {}).get("native_readback") is True
        unit["status"] = "VERIFIED" if verified else "DEFERRED"
        unit["result"] = {k: output[k] for k in
            ("phase", "reason", "drive_url", "artifact_sha256", "receipt", "canonical_writeback") if k in output}
    except Exception as exc:
        unit["status"] = "DEFERRED"
        # Never persist provider error bodies, bearer data, or model text.
        reason = str(exc) if isinstance(exc, ValueError) else type(exc).__name__
        known = {"daily_model_budget_reserved", "changed_source_requires_readmission",
                 "canonical_projection_refresh_required", "approval_source_changed", "canonical_projection_changed"}
        unit["result"] = {**unit.get("result",{}),"reason": reason if reason in known else "native_unit_deferred"}
    save(statefile, ledger)
    return result(unit["status"], unit=key, **unit["result"])

def execute(intake, budget):
    sys.path.insert(0, "/usr/local/lib/ziji-local-link")
    import local_inference_transport as local
    original = local.run
    def guarded(request):
        budget(request["request_id"])
        return original(request)
    local.run = guarded
    try:
        spec = importlib.util.spec_from_file_location("income_runtime", RUNTIME)
        module = importlib.util.module_from_spec(spec); spec.loader.exec_module(module)
        return module.execute(intake)
    finally:
        local.run = original

def drain(root=ROOT, queue=QUEUE, tickfn=tick, clock=time.monotonic, **kwargs):
    """One supervised run; no sleep, scheduler change, budget or backoff reset."""
    started = clock()
    initial = read(root / "state.json") if (root / "state.json").exists() else {}
    initial_used = sum(len(v) if isinstance(v,list) else bool(v) for v in initial.get("model_days",{}).values())
    seen = {initial.get("backlog_cursor",0)}
    scans = 0
    stop = "pass_limit"
    last = {"status":"WAITING","reason":"no_pass_executed"}
    passes = 0
    for _ in range(24):
        if clock()-started >= 120:
            stop = "time_limit"; break
        last = tickfn(root=root, queue=queue, **kwargs)
        passes += 1
        ledger = read(root / "state.json") if (root / "state.json").exists() else {}
        observation = ledger.get("backlog_observation",{})
        if observation.get("status") == "DEFERRED":
            stop = "source_or_authority_unavailable"; break
        if last["status"] not in ("VERIFIED","WAITING"):
            stop = last.get("reason","dependency_deferred"); break
        if last.get("reason") == "no_admitted_queue":
            stop = "no_admitted_queue"; break
        scanned = observation.get("scanned",0)
        total = observation.get("total_discovery_records",0)
        if type(scanned) is not int or type(total) is not int or not 0 < scanned <= total:
            stop = "no_discovery_progress"; break
        scans += scanned
        cursor = ledger.get("backlog_cursor",0)
        if scans >= total or cursor in seen:
            stop = "discovery_sweep_complete"; break
        seen.add(cursor)
    final = read(root / "state.json") if (root / "state.json").exists() else {}
    used = sum(len(v) if isinstance(v,list) else bool(v) for v in final.get("model_days",{}).values())
    report = dict(last, supervised={"passes":passes,"discovery_records_scanned":scans,
        "stop_reason":stop,"new_model_reservations":max(0,used-initial_used),
        "max_passes":24,"start_next_pass_within_seconds":120,"scheduler_changed":False},
        paid_fallback=False,submitted=0,contacted=0)
    save(root / "latest.json", report)
    return report

def main():
    if os.geteuid() != 0: raise SystemExit("root_required")
    ROOT.mkdir(parents=True, exist_ok=True, mode=0o700)
    with open(ROOT / "controller.lock", "a") as lock:
        os.chmod(ROOT / "controller.lock", 0o600)
        try: fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError: return
        income = Path("/var/lib/ziji-fabric/income")
        income.mkdir(parents=True, exist_ok=True, mode=0o700)
        fd = os.open(income / "unit.lock", os.O_CREAT | os.O_RDWR, 0o600)
        with os.fdopen(fd, "w") as native_lock:
            try: fcntl.flock(native_lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError: return
            from native_income_backlog import select,verify,writeback
            if sys.argv[1:] not in ([],["--drain"]):raise ValueError("invalid_mode")
            work = drain if "--drain" in sys.argv else tick
            print(json.dumps(work(invoke=execute,native_select=select,native_verify=verify,native_writeback=writeback),sort_keys=True))

if __name__ == "__main__":
    main()

