"""Standing bounded native Income research delegation; no application/send authority."""
import base64
import datetime as dt
import hashlib
import json
from pathlib import Path
import shlex
import stat
import sys
import urllib.request

AUTHORITY = {"ref":"RBO-97:12130","id":"12130",
    "updated":"2026-10-23T08:54:46.399-0500",
    "issuer":"712020:957ef1d2-89f5-461a-90e3-ffcfb77330bd"}
FOLDER = "1j_pa8A2sXBSA9vy87B6nyKo-myZ3HDaE"

def authority():
    sys.path.insert(0,"/opt/ziji-fabric/native")
    from collect_native_sources import config,request,JIRA_ROOT
    cfg=config("jira")
    if cfg.get("base_url")!=JIRA_ROOT or cfg.get("project_allowlist")!=["RBO"]:
        raise ValueError("jira_binding_scope_mismatch")
    token=base64.b64encode((cfg["email"]+":"+cfg["api_token"]).encode()).decode()
    value=request(JIRA_ROOT+"/rest/api/3/issue/RBO-97/comment/"+AUTHORITY["id"],
                  {"Authorization":"Basic "+token})
    validate_authority(value)

def validate_authority(value):
    if (value.get("updated")!=AUTHORITY["updated"] or
        any(value.get(k,{}).get("accountId")!=AUTHORITY["issuer"] for k in ("author","updateAuthor"))):
        raise ValueError("native_research_authority_changed")

def bridge(path, payload):
    env=Path("/etc/bridgeghl/bridgeghl.env")
    if env.is_symlink() or not stat.S_ISREG(env.stat().st_mode) or env.stat().st_uid!=0 or env.stat().st_mode & 0o077:
        raise ValueError("bridge_binding_private_file_required")
    keys=[]
    for line in env.read_text().splitlines():
        name,sep,value=line.partition("=")
        if sep and name.strip()=="BRIDGE_API_KEY":
            parsed=shlex.split(value,comments=True)
            if len(parsed)==1:keys.append(parsed[0])
    if len(keys)!=1 or not keys[0]:raise ValueError("bridge_binding_unavailable")
    class NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self,*args,**kwargs):return None
    req=urllib.request.Request("http://127.0.0.1:8000"+path,data=json.dumps(payload).encode(),
        headers={"x-api-key":keys[0],"Content-Type":"application/json"})
    with urllib.request.build_opener(urllib.request.ProxyHandler({}),NoRedirect).open(req,timeout=90) as response:
        raw=response.read(1048577)
        if len(raw)>1048576:raise ValueError("bridge_response_too_large")
        return json.loads(raw)

def entry_from(value,now):
    import re
    facts=value["facts"];ref=value["reference"]
    required={"provider","board","job_id","title","packet_id","do_not_submit","duplicate_clear","artifact_absent"}
    if (set(facts)!=required or value.get("native_readback") is not True or
        any(facts.get(k) is not True for k in ("do_not_submit","duplicate_clear","artifact_absent")) or
        facts["provider"] not in ("ashby","lever") or
        not re.fullmatch(r"[a-z0-9-]{1,60}",facts["board"]) or
        not re.fullmatch(r"[a-f0-9-]{36}",facts["job_id"]) or
        not re.fullmatch(r"[A-Za-z0-9-]{1,100}",facts["packet_id"]) or
        not re.fullmatch(r"https://app.notion.com/p/[a-f0-9]{32}",value["tracker_url"])):
        raise ValueError("native_backlog_facts_invalid")
    intake={k:facts[k] for k in ("provider","board","job_id","title","packet_id")}
    intake.update(tracker_url=value["tracker_url"],tracker_version=ref["current_source_sha256"],
                  observed_at=now.isoformat(),drive_folder=FOLDER)
    canonical={k:intake[k] for k in ("tracker_url","tracker_version","packet_id","job_id")}
    canonical.update(do_not_submit=True,highlevel=ref)
    return {"intake":intake,"canonical":canonical,"authority_ref":AUTHORITY["ref"],
            "expires_at":(now+dt.timedelta(hours=2)).isoformat(),
            "_native":{"facts":facts,"opportunity_updated":value.get("native_opportunity_updated")}}

def select(document,ledger,now,call=bridge,check=authority):
    check()
    result=call("/read/ingest/income-backlog",{"cursor":ledger.get("backlog_cursor",0),"limit":8})
    ledger["backlog_cursor"]=result["next_cursor"]
    ledger["backlog_observation"]={k:result.get(k) for k in
        ("scanned","total_discovery_records","rejection_counts","coverage")}
    ledger["backlog_observation"]["observed_at"]=now.isoformat()
    # Retain manual/Jira work and native unfinished recovery. Replace expired
    # discovery entries only when no effect/model request was ever started.
    from income_continuation import identity,timeof
    items=list(document["items"])
    known={identity(e["intake"]) for e in items}
    completed_jobs={u.get("job_identity") for u in ledger.get("units",{}).values() if u.get("status")=="VERIFIED"}
    for old in items:
        if ledger.get("units",{}).get(identity(old["intake"]),{}).get("status")=="VERIFIED":
            completed_jobs.add(":".join(old["intake"].get(k,"ashby" if k=="provider" else "") for k in ("provider","board","job_id")))
    retained=[]
    for old in items:
        unit=ledger.get("units",{}).get(identity(old["intake"]),{})
        if "_native" in old:
            if unit.get("status")=="VERIFIED":continue
            if not unit.get("request_id") and not unit.get("attempts") and now>=timeof(old["expires_at"]):continue
        retained.append(old)
    items=retained;known={identity(e["intake"]) for e in items}
    for value in result["items"]:
        entry=entry_from(value,now);key=identity(entry["intake"])
        job=":".join(entry["intake"][k] for k in ("provider","board","job_id"))
        if ledger.get("units",{}).get(key,{}).get("status")=="VERIFIED" or job in completed_jobs:continue
        if key in known:
            for i,old in enumerate(items):
                if identity(old["intake"])==key and "_native" in old and old["canonical"]["highlevel"]==entry["canonical"]["highlevel"]:
                    items[i]=entry
            continue
        if len(items)<32:items.append(entry);known.add(key)
    return {"version":1,"items":items}

def verify(entry,call=bridge,check=authority):
    check()
    ref=entry["canonical"]["highlevel"]
    value=call("/read/ingest/income-source",{k:v for k,v in ref.items() if k!="location_id"})
    if (not value.get("native_readback") or
        any(value.get(k)!=ref.get(k) for k in ("source_id","contact_id","opportunity_id","location_id")) or
        value.get("source_sha256")!=ref["current_source_sha256"]):
        raise ValueError("native_backlog_source_changed")
    if value.get("opportunity_updated")!=entry["_native"]["opportunity_updated"] or value.get("opportunity_status")!="open":
        raise ValueError("native_backlog_opportunity_changed")
    if value.get("source_version_count")!=1:
        raise ValueError("native_backlog_source_version_ambiguous")
    return value

def writeback(entry,output,call=bridge,check=authority):
    # Existing source-keyed writer owns effect dedupe; never manufacture another
    # packet or assert applicant qualification, contact, or submission.
    check()
    ref=entry["canonical"]["highlevel"]
    value=call("/read/ingest/income-source",{k:v for k,v in ref.items() if k!="location_id"})
    if (not value.get("native_readback") or value.get("source_sha256")!=ref["current_source_sha256"]
        or value.get("default_context_contact_id")!=ref["contact_id"]):
        raise ValueError("native_backlog_source_changed")
    if value.get("opportunity_updated")!=entry["_native"]["opportunity_updated"] or value.get("opportunity_status")!="open":
        raise ValueError("native_writeback_opportunity_changed")
    source=value["source"]
    props=dict(source["properties"])
    props["Native Artifact Link"]=output["drive_url"]
    props["Native Artifact SHA256"]=output["artifact_sha256"]
    props["Native Research Status"]="Research draft; not qualified; not packet-ready; not submitted"
    record={"domain":"income","source_id":ref["source_id"],"source_url":source["source_url"],
            "kind":"context","title":source["title"],"properties":props,"content":source.get("content","")}
    # Context writer targets only configured internal context. Historical records
    # attached to a real recruiter contact remain read-only pending specific route.
    expected=hashlib.sha256(json.dumps({"title":record["title"],"source_url":record["source_url"],
        "properties":props,"content":record["content"]},sort_keys=True,ensure_ascii=False,indent=2).encode()).hexdigest()
    if not set(value.get("source_versions",[])) <= {ref["current_source_sha256"],expected}:
        raise ValueError("native_writeback_source_changed")
    preview=call("/dry-run/ingest/source-record",record)
    if not preview.get("accepted") or preview.get("opportunity_effect")!="none":
        raise ValueError("native_writeback_preview_unavailable")
    result=call("/execute/ingest/source-record",record)
    if not result.get("verified") or result.get("contact_id")!=ref["contact_id"]:
        raise ValueError("native_writeback_identity_unverified")
    return {"status":"VERIFIED","source_key":result["source_key"],
            "note_ids":result["note_ids"],"native_readback":True}

